/*
 * Cancelados a columnas de la base.
 *
 * NO incluye `fecha_colectado`, por el mismo motivo que el flujo de pedidos no
 * toca `fecha_creacion`: es la columna con la que el tablero decide a qué mes
 * pertenece la cancelación. Si la corrida la reescribiera, el caso podría irse
 * del mes que alguien está mirando justo cuando aprieta Actualizar. La hora de
 * colecta además no cambia: es el primer registro del historial.
 *
 * La fecha de cancelación ya viene con las 3 horas restadas por la consulta, o
 * sea en hora de México, y se formatea con getters UTC para conservar ese reloj
 * de pared: la columna en Postgres es `timestamp` sin zona, y una segunda
 * conversión la correría de nuevo.
 */
const marca = (v) => (v ? new Date(v).toISOString().slice(0, 19).replace('T', ' ') : null);
const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};

return $input.all().map(({ json: r }) => ({
  json: {
    id: Number(r.Id),
    id_meli: texto(r.Id_MELI),
    tienda: texto(r.Tienda),
    estado_rbp: texto(r.Estado_RBP),
    estado_meli: texto(r.Estado_MELI),
    fecha_cancelado: marca(r.Fecha_Cancelado),
  },
})).filter((i) => Number.isFinite(i.json.id) && i.json.id > 0);
